class Solution {
public:
    vector<int> divisibilityArray(string word, int m) {
        int n = word.size();
        vector<int> div(n);
        long long r = 0;
        for (int i = 0; i < n; i++) {
            r = (r * 10 + (word[i] - '0')) % m;
            div[i] = (r == 0) ? 1 : 0;
        }
        return div;
    }
};
